#include "stdafx.h"#include "WVAR.h"KWVAR::KWVAR(): m_CurParameterID(-1), m_ReadParams( 0 ){}static LPCSTR s_MyParameters[]={  "Variable Number",};BOOL KWVAR::OnParsingSingleText( std::string &szText, RECTL *rc ){  if( m_CurParameterID!=-1 )  {    AddParam( s_MyParameters[m_CurParameterID], szText.c_str() );    CStringA s;    if( !m_CurParameterID )      s.Format( "VariableNumber = %d", atoi(szText.c_str()) );    if( !s.IsEmpty() )      m_settings.push_back( s.GetBuffer() );    m_CurParameterID = -1;    m_ReadParams++;    return TRUE;//сделать преобразование параметра к виду, пригодному для формирования исполняемого кода  }  for( int i=0; i<_countof(s_MyParameters); i++ )  {    if( szText.find(s_MyParameters[i])==0 )    {      m_CurParameterID = i;      return TRUE;    }  }  return FALSE;}